{
  "rules": [
    "If sentiment is positive (≥0.2) in recent days, model tends to overestimate prices; reduce forecast by 1–3% for 1–3 day horizon.",
    "If model shows steady upward trend with no volatility, true price often reverses or drops sharply within 5–10 days; add downward bias of 2–5% for 5–10 day horizon.",
    "After a sharp price spike (≥5% from prior peak), model often overshoots; cap forecast at +3% above prior peak for 3–7 day horizon.",
    "If sentiment is consistently neutral or negative (0.00), model tends to underestimate; add 1–2% upward bias for 1–5 day horizon.",
    "Model often fails to capture mean reversion in 10+ day horizons; if price deviates >5% from 30-day moving average, adjust forecast toward MA with 50% weight for 10+ day horizon.",
    "If sentiment history shows 3+ consecutive 0.00 values, model tends to be overly conservative; increase forecast by 1–3% for 1–3 day horizon."
  ]
}
